export const REPORT_CATALOG = ['Import Register', 'Export Register', 'Declaration Report', 'Duty Report', 'VAT Report', 'HS Code Report', 'Container Report', 'Shipment Report', 'Pending Declarations', 'Audit Report', 'Customs Stock / Inventory Report', 'Stock Reconciliation Report', 'Shipment Status Report', 'Duty Refund Report', 'Inspection Report', 'Bank Guarantee Utilization Report', 'Document Expiry Report', 'Hold & Release Report', 'Customs Transaction History', 'Inventory Balance', 'Stock Movement', 'Consumption / Production', 'Customs Reconciliation', 'Audit Trail'];
export function tallyVoucherXml(entries) { const body = entries.map(e => `<VOUCHER><DATE>${e.date.replaceAll('-', '')}</DATE><VOUCHERNUMBER>${e.number}</VOUCHERNUMBER><ALLLEDGERENTRIES.LIST><LEDGERNAME>${e.ledger}</LEDGERNAME><AMOUNT>${e.amount.toFixed(2)}</AMOUNT></ALLLEDGERENTRIES.LIST></VOUCHER>`).join(''); return `<ENVELOPE><HEADER><TALLYREQUEST>Import Data</TALLYREQUEST></HEADER><BODY><IMPORTDATA><REQUESTDATA>${body}</REQUESTDATA></IMPORTDATA></BODY></ENVELOPE>`; }
